describe("explicit configured OAuth application provider", () => {
  let fixture: Awaited<ReturnType<typeof oauthFixture>> | undefined;
  afterEach(async () => fixture?.close());

  it("T-AC-54 T-AC-62 completes a real local PKCE exchange into the exact application's session", async () => {
    fixture = await oauthFixture();
    const start = await fixture.start();
    expect(start.status).toBe(200);
    const callback = await fixture.callback(start);
    expect(callback.status).toBe(302);
    expect(callback.headers.get("location")).toBe(`${fixture.backend.baseUrl}/signed-in`);
    expect(fixture.providerState.exchanges).toBe(1);
    expect(fixture.providerState.profiles).toBe(1);
    expect(fixture.providerState.verifier.length).toBeGreaterThan(20);
    const session = await fixture.backend.request("/auth/get-session", {
      headers: { cookie: appCookie(callback) },
    });
    expect(await session.json()).toMatchObject({
      user: { email: "oauth@example.test", name: "Local OAuth fixture" },
    });
    const replay = await fixture.backend.request("/auth/get-session");
    expect(await replay.json()).toBeNull();
  });

  it("T-AC-54 rejects altered OAuth state before making the private exchange", async () => {
    fixture = await oauthFixture();
    const start = await fixture.start();
    expect(start.status).toBe(200);
    const callback = await fixture.callback(start, (url) =>
      url.searchParams.set("state", "synthetic-foreign-state"),
    );
    expect(callback.status).toBeGreaterThanOrEqual(300);
    expect(fixture.providerState.exchanges).toBe(0);
    const session = await fixture.backend.request("/auth/get-session", {
      headers: { cookie: appCookie(callback) },
    });
    expect(await session.json()).toBeNull();
  });

  it("T-AC-54 rejects a foreign OAuth callback origin without contacting the provider", async () => {
    fixture = await oauthFixture();
    const response = await fixture.backend.json("/auth/sign-in/social", {
      provider: "fixture",
      callbackURL: "https://foreign.example.test/callback",
      disableRedirect: true,
    });
    expect(response.status).toBeGreaterThanOrEqual(400);
    expect(response.status).toBeLessThan(500);
    expect(fixture.providerState.exchanges).toBe(0);
  });
});
